//! The `settings` commands: view, explain and change adjustable behaviour.

use thingamaroo_core::configuration::{RuntimeSettings, SettingEntry, describe_setting};
use thingamaroo_core::error::BrainResult;

use crate::arguments::SettingsAction;
use crate::commands::Invocation;

const PATH_SEPARATOR: char = '.';

const REFERENCE_INTRODUCTION: &str = "\
# Settings reference

<!-- Generated by `thingamaroo settings reference`. Do not edit by hand: change the
     doc comments in crates/core/src/configuration/settings.rs and regenerate. -->

Settings are the behaviour of a brain that can be changed at any time without
retraining. They live in `settings.json` inside the brain folder.

- Command line: `thingamaroo settings show`, `thingamaroo settings set <path> <value>`,
  `thingamaroo settings reset`.
- Desktop application: the **Settings** tab.

Values are written as JSON: numbers, `true`/`false`, text, `[\"a\", \"list\"]`, or `null`
for \"none\". The defaults below are what a new brain starts with.
";

/// Runs one settings action.
pub fn run(invocation: &Invocation, action: SettingsAction) -> BrainResult<()> {
    match action {
        SettingsAction::Reference => print_reference(),
        SettingsAction::Show => print_settings(invocation.open_brain()?.settings()),
        SettingsAction::Set { path, value } => set_setting(invocation, &path, &value)?,
        SettingsAction::Reset => reset_settings(invocation)?,
    }
    Ok(())
}

fn set_setting(invocation: &Invocation, path: &str, value: &str) -> BrainResult<()> {
    let mut brain = invocation.open_brain()?;
    let changed = brain.settings().with_entry_text(path, value)?;
    brain.replace_settings(changed)?;
    println!("{path} = {value}");
    println!("    {}", describe_setting(path));
    Ok(())
}

fn reset_settings(invocation: &Invocation) -> BrainResult<()> {
    let mut brain = invocation.open_brain()?;
    brain.replace_settings(RuntimeSettings::default())?;
    println!("Every setting restored to its default.");
    Ok(())
}

/// Prints every setting of a brain with its value and what it does.
fn print_settings(settings: &RuntimeSettings) {
    for group_entries in grouped(&settings.entries()) {
        let group_name = group_name(&group_entries[0]);
        println!("\n[{group_name}] {}", describe_setting(group_name));
        for entry in group_entries {
            println!("  {} = {}", entry.path, entry.value);
            println!("      {}", entry.description);
        }
    }
}

/// Prints the default settings as a Markdown document.
fn print_reference() {
    println!("{REFERENCE_INTRODUCTION}");
    for group_entries in grouped(&RuntimeSettings::default().entries()) {
        let group_name = group_name(&group_entries[0]);
        println!("## {group_name}\n");
        println!("{}\n", describe_setting(group_name));
        println!("| Setting | Default | What it does |");
        println!("| --- | --- | --- |");
        for entry in group_entries {
            println!(
                "| `{}` | `{}` | {} |",
                entry.path, entry.value, entry.description
            );
        }
        println!();
    }
}

/// Splits entries into runs that share a group, keeping their order.
fn grouped(entries: &[SettingEntry]) -> Vec<&[SettingEntry]> {
    entries
        .chunk_by(|left, right| group_name(left) == group_name(right))
        .collect()
}

fn group_name(entry: &SettingEntry) -> &str {
    entry
        .path
        .split(PATH_SEPARATOR)
        .next()
        .unwrap_or(&entry.path)
}
